cards.styles:
.bubble-button-card-container {
  --sky-night: linear-gradient(180deg, #0b1430, #1d2b55 70%, #3a4a78);
  --sky-night-grey: linear-gradient(180deg, #141a27, #262e40 70%, #3c4458);
  --sky-twilight: linear-gradient(180deg, #2b3a6b, #b0627a 65%, #f0a868);
  --sky-twilight-grey: linear-gradient(180deg, #3a4060, #7a6878 65%, #a88f88);
  --sky-clear: linear-gradient(180deg, #2f7fc8, #79b8e8 70%, #c4e2f6);
  --sky-partly: linear-gradient(180deg, #4f86b8, #97bad8 70%, #cfdde9);
  --sky-cloudy: linear-gradient(180deg, #66778a, #9eabb8 75%, #c1cad3);
  --sky-fog: linear-gradient(180deg, #8f99a3, #b9c0c7 70%, #d5dadf);
  --sky-rain: linear-gradient(180deg, #3f4c5a, #6f7d8b 75%, #8e9aa6);
  --sky-storm: linear-gradient(180deg, #23283a, #48506a 70%, #6a6f86);
  --sky-snow: linear-gradient(180deg, #8a9bb0, #c3cfdc 70%, #e8eef4);
  background: ${__LAYERS__} !important;
  border-radius: var(--ha-card-border-radius, 12px) var(--ha-card-border-radius, 12px) 0 0 !important;
}
.bubble-name, .bubble-state, .bubble-sub-button { color: #fff !important; text-shadow: 0 1px 3px rgba(0, 0, 0, .55), 0 0 10px rgba(0, 0, 0, .25); }
.bubble-content-container { margin-top: 22px !important; }
.bubble-sub-button { font-size: 13px !important; }
.bubble-sub-button-bottom-container { padding-inline-start: 6px !important; padding-bottom: 4px !important; }
.bubble-name-container { line-height: normal !important; overflow: visible !important; gap: 4px; margin-inline: 14px 16px !important; }
.bubble-name { font-size: 14px !important; font-weight: 600 !important; letter-spacing: .2px; opacity: .92; }
.bubble-state { font-size: 30px !important; font-weight: 600 !important; line-height: 1.05 !important; opacity: 1 !important; }
.bubble-icon-container { margin-inline-start: 14px !important; min-width: 48px !important; min-height: 48px !important; }
.bubble-main-icon-container { background-color: rgba(255, 255, 255, .22) !important; }
.bubble-main-icon { color: #fff !important; }
.bubble-sub-button-1 .bubble-sub-button-icon { color: var(--cyan-color) !important; }
.bubble-sub-button-2 .bubble-sub-button-icon { color: #cfd8dc !important; }
.bubble-sub-button-3 .bubble-sub-button-icon { color: var(--light-blue-color) !important; }
.bubble-sub-button-4 .bubble-sub-button-icon { color: var(--orange-color) !important; }
